/**
 * The waiter-call alert tone, inlined as a data URI.
 *
 * Generated once (22.05 kHz mono 16-bit PCM: two rising notes, played
 * twice) and committed as text rather than shipped as a binary asset -
 * nothing to download separately on restaurant wifi, and nothing that can
 * 404 after a deploy.
 *
 * It is a real audio file rather than a Web Audio oscillator because an
 * <audio> element is far easier to unlock on a phone: one play() inside a
 * real tap permanently authorises later programmatic playback, including
 * on iOS, where the Web Audio route kept losing the race.
 */
export const WAITER_ALERT_WAV =
  "data:audio/wav;base64,";
